    @Test func vectorResizingFromUInt8() {
        let mismatches = Mismatches("portVectorResizingU8ToI64InVectorCode")
        let aInputs = Inputs.conversions(SIMD<UInt8>.self, seed: 0x2305_29E0_092C_EC12)
        for a in aInputs {
            let port = { () -> SIMD<Int64> in
                var a = a
                return withUnsafeTemporaryAllocation(of: SIMD<Int64>.self, capacity: 1) { result in
                    unsafe portVectorResizingU8ToI64InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        resizing: &a
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let reference = { () -> SIMD<Int64> in
                var a = a
                return withUnsafeTemporaryAllocation(of: SIMD<Int64>.self, capacity: 1) { result in
                    unsafe highwayVectorResizingU8ToI64InVectorCode(
                        result.baseAddress.unsafelyUnwrapped,
                        resizing: &a
                    )
                    return unsafe result.baseAddress.unsafelyUnwrapped.move()
                }
            }()
            let definedBytes = SIMD<UInt8>.laneCount * MemoryLayout<UInt8>.stride
            let grownBytes = H.laneCount * MemoryLayout<Lane>.stride
            let newBytes = HighwayReference.resizedBytesDefined(
                definedBytes,
                grownBytes,
                definedBytes
            )
            mismatches.check(
                Array(bytes(of: port).prefix(definedBytes)),
                Array(bytes(of: reference).prefix(definedBytes)),
                "a: \(describe(a))"
            )
            mismatches.check(
                Array(registerBytes(of: port).dropFirst(definedBytes).prefix(newBytes)),
                Array(registerBytes(of: reference).dropFirst(definedBytes).prefix(newBytes)),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

